from batch07 import *
start('vlan','VLAN — głos, SVI i diagnostyka trunków','2.1',['https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst3650/software/release/16-12/command_reference/b_1612_3650_cr/layer_2_3_commands.html','https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst3750x_3560x/software/release/15-0_2_se/configuration/guide/3750x_cg/swint.html'],True)
q('Telefon i komputer','Telefon obsługuje voice VLAN, a PC jest podłączony za telefonem. Jaki układ jest typowy na porcie switcha?','Access VLAN dla danych oraz osobny voice VLAN',['Dwa różne access VLAN-y jednocześnie|Pojedynczy port nie ma dwóch zwykłych access VLAN-ów w tym modelu.','Wyłącznie routed port bez L2|To nie typowy port telefonu z PC w VLAN-ach.','Brak VLAN-u dla ruchu PC|Nieotagowany ruch nadal trafia do VLAN-u danych.'],'Obsługiwany telefon może tagować głos, a ruch PC pozostać w access VLAN.')
q('Dynamic auto po obu stronach','Oba końce obsługują DTP i mają dynamic auto. Czy sam ten układ negocjuje trunk?','Nie',['Tak, auto aktywnie wymusza trunk|Auto oczekuje inicjatywy drugiej strony.','Tak, jeśli port jest gigabitowy|Szybkość fizyczna nie zmienia tego zachowania DTP.','Tak, jeśli hostnames są identyczne|Hostname nie jest kryterium DTP.'],'Dwa pasywne końce auto nie są wystarczającym warunkiem utworzenia trunku.')
c('Telefon: dwa VLAN-y','Port jest już statycznym access. Ustaw data VLAN 10 i voice VLAN 20 dla obsługiwanego telefonu.','SW(config-if)# switchport access vlan {{b0}}\nSW(config-if)# switchport voice vlan {{b1}}',['10','20'],'Voice VLAN nie zastępuje przypisania danych do access VLAN.')
q('Wyłączenie DTP','Co robi switchport nonegotiate na statycznym trunku?','Wyłącza generowanie ramek DTP',['Wyłącza ruch wszystkich VLAN-ów|Nonegotiate nie jest shutdown ani pustą listą allowed.','Zmienia trunk na routed port|Do tego służy inna konfiguracja.','Automatycznie ustala native VLAN 99|Nie zmienia numeru native VLAN.'],'Tryb trunk trzeba zapewnić konfiguracją; wyłączenie negocjacji nie wyłącza trunku.')
c('Statyczny trunk bez negocjacji','Po obu stronach uzgodniono statyczny trunk 802.1Q. Na tym końcu ustaw trunk i wyłącz DTP.','SW(config-if)# switchport mode {{b0}}\nSW(config-if)# switchport {{b1}}',['trunk','nonegotiate'],'Sąsiad również musi mieć poprawny tryb, szczególnie gdy nie korzysta z DTP.')
q('SVI a port fizyczny','Czym jest interface Vlan30 na przełączniku warstwy trzeciej?','Logicznym interfejsem L3 dla VLAN 30',['Zawsze fizycznym portem numer 30|Numer VLAN-u nie jest numerem gniazda.','Listą wszystkich trunków|SVI jest interfejsem, nie listą portów.','Automatycznie serwerem DHCP|SVI nie uruchamia sam z siebie DHCP.'],'SVI może pełnić rolę bramy lub interfejsu zarządzania zależnie od projektu.')
q('SVI down przy no shutdown','VLAN istnieje, SVI ma no shutdown, ale brak aktywnego portu forwarding w tym VLAN-ie. Przy standardowym autostate co może się dziać?','Line protocol SVI pozostaje down',['SVI zawsze musi być up|Autostate uwzględnia stan portów VLAN-u.','VLAN zmienia numer automatycznie|To nie efekt autostate.','Switch usuwa wszystkie adresy MAC globalnie|Nie jest to konieczny skutek.'],'Samo no shutdown nie spełnia wszystkich warunków operacyjnego stanu SVI.')
q('Allowed nie tworzy VLAN-u','Dodano VLAN 40 do allowed trunku, ale VLAN 40 nie istnieje lokalnie. Co jeszcze trzeba zapewnić?','Istnienie i aktywność VLAN 40',['Tylko zmianę hasła enable|Nie tworzy VLAN-u.','Zwiększenie router ID|Nie wpływa na bazę VLAN.','Usunięcie 802.1Q z trunku|Zniszczyłoby wymagany transport VLAN-ów.'],'Lista dozwolonych VLAN-ów nie zastępuje utworzenia VLAN-u w lokalnej bazie.')
c('SVI dla użytkowników','Na switchu L3 istnieje aktywny VLAN 30. Włącz routing IPv4, nadaj SVI adres 192.168.30.1/24 i administracyjnie je podnieś.','SW(config)# ip {{b0}}\nSW(config)# interface Vlan30\nSW(config-if)# ip address {{b1}} 255.255.255.0\nSW(config-if)# {{b2}}',['routing',(['192.168.30.1'],'ipv4'),'no shutdown'],'Routing między SVI wymaga obsługi L3 i włączenia routingu; stan SVI zależy również od VLAN-u.')
q('Zarządzanie L2','Switch działa z wyłączonym ip routing i ma SVI zarządzania. Jaką funkcję pełni ip default-gateway?','Wskazuje bramę dla ruchu IP samego switcha poza lokalną podsieć',['Routuje automatycznie między wszystkimi VLAN-ami|To nie włącza routingu użytkowników.','Zmienia bramę każdego PC przez ARP|Nie konfiguruje bram hostów.','Wybiera root STP|Nie jest parametrem STP.'],'Brama zarządzania switcha L2 i routing między VLAN-ami to różne funkcje.')
c('Zarządzanie bez routingu','Switch L2 ma aktywny VLAN 99 i wyłączone ip routing. Ustaw SVI 10.99.0.2/24, podnieś je i wskaż bramę 10.99.0.1.','SW(config)# interface Vlan99\nSW(config-if)# ip address {{b0}} 255.255.255.0\nSW(config-if)# {{b1}}\nSW(config-if)# exit\nSW(config)# ip default-gateway {{b2}}',[(['10.99.0.2'],'ipv4'),'no shutdown',(['10.99.0.1'],'ipv4')],'SVI umożliwia zarządzanie IP, a brama służy dotarciu poza jego podsieć.')
q('VLAN a podsieć','Dlaczego w typowym projekcie przypisuje się różne podsieci IP do różnych VLAN-ów użytkowników?','VLAN-y rozdzielają domeny L2, a komunikacja między nimi wymaga odpowiedniej funkcji L3',['Bo numer VLAN musi równać się ostatniemu oktetowi IP|Nie ma takiego wymogu.','Bo 802.1Q przenosi maskę IPv4|Tag VLAN nie przenosi maski podsieci.','Bo każdy VLAN wymaga publicznego IP|VLAN może używać adresacji prywatnej.'],'Przejrzyste mapowanie VLAN–podsieć ułatwia routing i diagnostykę; sam numer VLAN nie definiuje IP.')
q('Native mismatch w praktyce','Na jednym końcu native VLAN to 10, na drugim 20; standardowo native jest nietagowany. Co grozi ramkom nietagowanym?','Zostaną przypisane do różnych VLAN-ów na końcach',['Automatycznie dostaną tag 4095|To nie zachowanie naprawcze native mismatch.','Zawsze zostaną zaszyfrowane|802.1Q nie szyfruje danych.','Zmienią się w pakiety IPv6|Tagowanie nie zmienia protokołu IP.'],'Niezgodna interpretacja ruchu nietagowanego może naruszyć segmentację i łączność.')
q('Trunk a STP','VLAN 50 jest allowed i active, ale port dla niego jest w stanie STP discarding. Czy sam allowed gwarantuje forwarding?','Nie',['Tak, allowed ma pierwszeństwo przed STP|STP nadal kontroluje przekazywanie.','Tak, jeśli port ma 1 Gb/s|Szybkość nie wyłącza STP.','Tak, jeśli VLAN jest nazwany USERS|Nazwa VLAN-u nie steruje stanem STP.'],'Transport VLAN-u zależy również od stanu STP i pozostałych warunków operacyjnych.')
c('Utwórz, dodaj, sprawdź','Utwórz VLAN 55, dodaj go do już działającego trunku G1/0/24 bez usuwania innych VLAN-ów i wyświetl trunki.','SW(config)# vlan {{b0}}\nSW(config-vlan)# exit\nSW(config)# interface GigabitEthernet1/0/24\nSW(config-if)# switchport trunk allowed vlan {{b1}} 55\nSW(config-if)# end\nSW# show interfaces {{b2}}',['55','add','trunk'],'Kolejność pozwala przygotować lokalny VLAN i rozszerzyć istniejący transport bez nadpisania listy.')
q('PC bez tagów','Na statycznym access VLAN 70 PC wysyła zwykłą nieotagowaną ramkę. Do którego VLAN-u jest ona przypisana?','VLAN 70',['Zawsze VLAN 1|Access VLAN został jawnie ustawiony na 70.','Do żadnego VLAN-u|Nieotagowany ruch na access nadal ma przypisanie VLAN.','Do VLAN-u równego portowi TCP|Port transportowy nie wybiera access VLAN-u.'],'Przypisanie na wejściu wynika z konfiguracji portu access, a nie tagu dodanego przez PC.')
c('Pełny port telefonu','VLAN 110 dla danych i 120 dla głosu istnieją. Ustaw port jako access, przypisz oba VLAN-y i wyłącz DTP.','SW(config-if)# switchport mode {{b0}}\nSW(config-if)# switchport access vlan {{b1}}\nSW(config-if)# switchport voice vlan {{b2}}\nSW(config-if)# switchport {{b3}}',['access','110','120','nonegotiate'],'Port telefonu z PC wymaga świadomego rozdzielenia danych i głosu; negocjacja trunku nie jest do tego potrzebna.')
q('Brama jest osiągalna, zdalny VLAN nie','PC pinguje własną bramę SVI, lecz nie hosta innego VLAN-u. Co sprawdzić dalej?','Routing, polityki oraz drogę powrotną i stan docelowego hosta',['Uznać, że ping do bramy dowodzi całej ścieżki|To potwierdza tylko część drogi.','Od razu zmienić MAC wszystkich urządzeń|Nie jest celowaną diagnostyką.','Usunąć numer VLAN ze wszystkich portów|To może zniszczyć działający fragment sieci.'],'Łączność lokalna nie przesądza o routingu, filtrach i odpowiedzi końca zdalnego.')
end()
